"use strict";
const modules=[['control','◈','Control Tower','Overview and release posture'],['market','▥','Market Intelligence','Market breadth / sectors'],['stock','⌕','Stock Intelligence','Ticker and provenance'],['scanner','◎','Scanner Center','EBB / DSI / SNIPER'],['engine','⬡','Engine Center','Independent locked engines'],['broker','⇄','Broker Flow','Bandar DSI intelligence'],['corporate','▤','Corporate Actions','Events and disclosures'],['shareholder','♙','Shareholder Intelligence','SIE ownership history'],['portfolio','◫','Portfolio Intelligence','Private position concepts'],['watchlist','☆','Watchlist','Personal tracking concepts'],['reports','▣','Reports & Infographics','Export presentation'],['connectors','⌁','Connector Center','Gigantum and ARJUM'],['diagnostics','⚙','Diagnostics','Release gate and health']];
const descriptions={control:'Executive intelligence overview · system posture and source integrity.',market:'Market breadth, sector rotation, and regime visualization.',stock:'Ticker research workspace · source identity, validation, and provenance.',scanner:'Multi-engine discovery · candidate lifecycle and risk controls.',engine:'Specialized intelligence engines · locked independent baselines.',broker:'Broker inventory and smart-money flow · no live provider access.',corporate:'Corporate actions, catalysts, and event intelligence.',shareholder:'Shareholder Intelligence Engine · ownership threshold above 1%.',portfolio:'Portfolio exposure and concentration · no personal holdings.',watchlist:'Personal monitoring workspace · no browser persistence.',reports:'Institutional research reports and visual exports.',connectors:'Official provider integration and contract readiness.',diagnostics:'Operational health, deployment controls, and release governance.'};
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current='control';
function toast(s){document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.textContent=s;document.body.append(d);setTimeout(()=>d.remove(),3600)}
function metric(label,value,sub,cls=''){return `<div class="card"><div class="label">${label}</div><div class="metric ${cls}">${value}</div><div class="micro">${sub}</div></div>`}
function section(title,body,note=''){return `<div class="section"><div class="section-head"><h2>${title}</h2><span>${note}</span></div>${body}</div>`}
function chart(kind){let pts=Array.from({length:25},(_,i)=>{let y=kind==='line'?115-Math.sin(i*.44)*25-Math.cos(i*.85)*13-i*.5:130-Math.cos(i*.35)*18+Math.sin(i*.78)*11;return `${12+i*20},${Math.max(30,Math.min(172,y)).toFixed(1)}`}).join(' ');let bars=Array.from({length:18},(_,i)=>`<rect x="${12+i*27}" y="${155-(i*11+25)%92}" width="14" height="${(i*11+25)%92}" rx="2" fill="${i%3?'#947449':'#d3ae6c'}" opacity=".75"/>`).join('');return `<svg class="chart" viewBox="0 0 520 190" preserveAspectRatio="none" role="img" aria-label="Illustrative ${kind} chart DEMO">${[35,75,115,155].map(y=>`<path d="M0 ${y} H520" stroke="#2a3648" stroke-dasharray="3 6"/>`).join('')}${kind==='bars'?bars:`<polyline points="${pts}" fill="none" stroke="#d4ad67" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${pts} 492,175 12,175" fill="#d4ad67" opacity=".08"/>`}</svg><div class="legend">ILLUSTRATIVE SHAPE ONLY · NO PRICES / NO MARKET FEED</div>`}
function table(headers,rows){return `<div class="card" style="overflow-x:auto"><table class="rows"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function empty(title,body){return `<div class="empty"><div class="bigicon">◇</div><h3>${title}</h3><p>${body}</p></div>`}
function control(){return `<div class="v21-toolbar"><span class="v21-tag">INTERACTIVE WORKSPACE v2.4 · DEMO</span><button class="mini-btn" data-action="alerts">View alert policy</button><button class="mini-btn" data-action="source">Source integrity</button></div><div class="grid four">${metric('Validated OHLCV','0','NO AUTHENTIC RECORDS','gold')}${metric('Live scanner candidates','0','ALL SCANNERS DISABLED')}${metric('Connected providers','0 / 2','GIGANTUM + ARJUM','red')}${metric('Release gate','BLOCK','STAGING / PRODUCTION','red')}</div><div class="grid two section"><div class="card chart-panel"><div class="section-head"><h2>Market Structure · DEMO</h2><span>ILLUSTRATIVE</span></div>${chart('line')}</div><div class="card chart-panel"><div class="section-head"><h2>Participation & Breadth · DEMO</h2><span>ILLUSTRATIVE</span></div>${chart('bars')}</div></div>${scenarioWorkspace()}${section('Intelligence Readiness',table(['LAYER','CURRENT STATE','VALIDATION'],[['SCAN EBB','<span class="state gray">LOCKED</span>','Data unavailable'],['SCAN DSI','<span class="state gray">LOCKED</span>','Data unavailable'],['BANDAR DSI','<span class="state gray">LOCKED</span>','Provider unavailable'],['Source governance','<span class="state red">BLOCK</span>','No authenticated ingestion']]),'READ-ONLY CONCEPT')}${section('Operational Roadmap · DEMO',`<div class="grid three">${metric('1 · Interface','PREVIEW','STATIC HTML · PUBLIC DEMO','gold')}${metric('2 · Source admission','BLOCKED','GIGANTUM + ARJUM NOT_CONNECTED','red')}${metric('3 · Production','BLOCKED','PERSISTENCE / HTTPS / AUTH REQUIRED','red')}</div>`,'NOT A RELEASE CERTIFICATION')}`}
function market(){return `<div class="v21-toolbar"><label for="v21-timeframe">Illustrative timeframe</label><select id="v21-timeframe"><option>Daily</option><option>Weekly</option><option>Monthly</option></select><button class="mini-btn" data-action="regime">Explain regime</button><span id="v21-feedback" class="v21-tag">Daily · DEMO</span></div><div class="grid four">${metric('IHSG','—','NO LIVE INDEX DATA')}${metric('Market breadth','—','SOURCE NOT CONNECTED')}${metric('Sector leaders','—','UNAVAILABLE')}${metric('Market regime','UNVERIFIED','NO CALCULATED SIGNAL','red')}</div><div class="grid two section"><div class="card"><h3>Index structure · DEMO</h3>${chart('line')}</div><div class="card"><h3>Sector rotation · DEMO</h3>${chart('bars')}</div></div>${scenarioWorkspace()}${section('Data coverage',empty('No validated market data','Visual charts above are decorative synthetic shapes. No historical or real-time IDX data is used.'))}`}
function stock(){return `<div class="v21-toolbar"><button class="mini-btn" data-action="provenance">Provenance checklist</button><button class="mini-btn" data-action="risk">Risk policy</button></div><div class="tools"><input id="ticker" class="field" placeholder="Contoh ticker: BBCA (DEMO)" maxlength="12" aria-label="Ticker preview"><select id="tf"><option>Daily</option><option>Weekly</option><option>Monthly</option></select><button id="lookup" class="mini-btn">Preview lookup ↗</button></div><div class="grid four">${metric('Source kind','UNAVAILABLE','NO SOURCE QUERY')}${metric('Source as-of','—','NO SOURCE TIMESTAMP')}${metric('Validation','BLOCKED','NO VERIFIED OHLCV','red')}${metric('Provenance','UNVERIFIED','NO PROVIDER EVIDENCE','red')}</div>${section('Stock research canvas',`<div class="grid two"><div class="card"><h3>Price structure · DEMO</h3>${chart('line')}</div><div class="card"><h3>Volume biography · DEMO</h3>${chart('bars')}</div></div>`)}${section('Ticker verification workspace · DEMO',`<div id="ticker-result" class="notice" role="status">Masukkan ticker untuk melihat daftar pemeriksaan sumber. Tidak ada data saham yang diambil.</div>`)}${section('Evidence ledger',empty('Ticker data unavailable','Search is a UI interaction only. No ticker data, broker records, scores, entries, or probabilities are generated.'))}`}
function scanner(){return `<div class="tools"><select id="engine-select"><option>SCAN EBB</option><option>SCAN DSI</option><option>SNIPER</option><option>HOLYGRAIL</option><option>VMS-PRO</option></select><select id="time-select"><option>Daily</option><option>Weekly</option></select><button id="run" class="mini-btn">Run DEMO check</button></div><div class="grid four">${metric('Universe','0','VALIDATED TICKERS')}${metric('Qualified candidates','0','NO DATA INPUT')}${metric('Probability','—','NO HISTORICAL BACKTEST')}${metric('Signal state','DISABLED','LONG-ONLY IDX','red')}</div>${section('Scanner results',empty('No authentic candidates','The scanner is not executed in this static preview. Scores, probability, entry, stop loss, and targets remain unavailable.'))}`}
function engine(){return `<div class="v21-toolbar"><button class="mini-btn" data-action="engines">Show engine governance</button><span class="v21-tag">THREE MASTERS · ZERO CHANGE</span></div><div class="notice">THREE MASTERS. ONE ECOSYSTEM. ZERO CHANGE. All module tiles are presentation-only and cannot modify the locked engines.</div>${engineComparison()}${section('Three Masters',`<div class="module-grid">${[['SCAN EBB','Extreme Bandar Breakout'],['SCAN DSI','Demand & Smart-money Reversal'],['BANDAR DSI','Broker Flow Intelligence']].map(([a,b])=>tile(a,b)).join('')}</div>`)}${section('Specialized Intelligence',`<div class="module-grid">${[['SNIPER','Demand × Retest × CHoCH'],['HOLYGRAIL','Core / Seasonality'],['VMS-PRO','Momentum & Volume'],['FRI-01','Five-Room Intelligence'],['SIE','Shareholder Intelligence'],['ONCI','News & Catalyst Intelligence'],['BIOGRAFI VOLUME','Volume profile research'],['P-FLOW','Standalone demand momentum'],['CORPORATE ACTION','CA Intelligence']].map(([a,b])=>tile(a,b)).join('')}</div>`,'INDEPENDENT ENGINE PRESENTATIONS')}`}
function tile(name,desc){return `<button class="module-tile" data-tile="${esc(name)}"><div class="symbol">◇</div><strong>${esc(name)}</strong><small>${esc(desc)}<br>DEMO · NO EXECUTION</small></button>`}
function broker(){return `<div class="v21-toolbar"><label for="v21-broker">Broker focus</label><select id="v21-broker"><option>AK</option><option>ZP</option><option>KZ</option><option>BK</option><option>AI</option><option>RX</option><option>CS</option><option>YU</option></select><span id="v21-broker-label" class="v21-tag">AK · no live records</span></div><div class="grid four">${metric('Broker records','0','NO VERIFIED INVENTORY')}${metric('Foreign flow','—','SOURCE UNAVAILABLE')}${metric('Consensus','UNAVAILABLE','NO SOURCE VALIDATION')}${metric('ARJUM','NOT_CONNECTED','PROVIDER ENTITLEMENT PENDING','red')}</div>${section('Broker Intelligence',table(['BROKER CODE','DATA STATUS','AVG PRICE'],[['AK','Unavailable','—'],['ZP','Unavailable','—'],['KZ','Unavailable','—'],['BK','Unavailable','—'],['AI / RX / CS / YU','Unavailable','—']]))}`}
function corporate(){return `<div class="grid three">${metric('Verified events','0','NO OFFICIAL DISCLOSURE')}${metric('Upcoming actions','—','NO INGESTION')}${metric('Event confidence','UNVERIFIED','SOURCE NOT CONNECTED')}</div>${section('Corporate Action Calendar',empty('No verified corporate actions','IDX/OJK/emiten disclosures have not been ingested into this public preview.'))}`}
function shareholder(){return `<div class="grid three">${metric('Ownership threshold','> 1%','SIE SPECIFICATION ONLY')}${metric('History target','36 months','NOT INGESTED')}${metric('Reconciliation','PENDING','KSEI / IDX / ISSUER')}</div>${section('Ownership intelligence',empty('No shareholder records','Source reconciliation has not been executed in this static preview.'))}`}
function portfolio(){return `<div class="grid three">${metric('Positions','0','NO USER DATA')}${metric('Portfolio value','—','NO ACCOUNT / STORAGE')}${metric('Risk exposure','—','NOT COMPUTED')}</div>${section('Portfolio workspace',empty('Private portfolio unavailable','This public preview has no login, session, browser storage, database, or personal financial information.'))}`}
function watchlist(){return `<div class="tools"><input id="watch-input" class="field" placeholder="Ticker contoh (tidak disimpan)" maxlength="12"><button id="watch-add" class="mini-btn">Try preview action</button></div>${section('Watchlist workspace',empty('No watchlist is stored','Preview actions do not save anything locally or remotely. The actual EDIE watchlist remains isolated.'))}`}
function reports(){return `<div class="grid three">${metric('Reports generated','0','NO OPERATIONAL EXPORT')}${metric('Infographics','DEMO','PRESENTATION ONLY')}${metric('Evidence completeness','UNAVAILABLE','NO PROVENANCE')}</div>${section('Research outputs',`<div class="module-grid">${[['Equity Research','Institutional equity report'],['Market Intelligence','Market breadth review'],['Corporate Actions','Event impact briefing']].map(([a,b])=>tile(a,b)).join('')}</div>`)}`}
function connectors(){return `<div class="grid two">${['Gigantum','ARJUM'].map((x)=>`<div class="card"><div class="section-head"><h2>${x} Connector</h2><span class="state red">NOT_CONNECTED</span></div><div class="metric gold">OFFLINE</div><div class="micro">${x==='Gigantum'?'Official OHLCV export and provenance required.':'Provider entitlement, official access and authenticated payload required.'}</div><div class="bar"><span style="width:0%"></span></div></div>`).join('')}</div>${section('Source integrity gates',table(['GATE','REQUIREMENT','STATE'],[['Source identity','Official authorization','BLOCKED'],['Timestamp & provenance','Authenticated source as-of','BLOCKED'],['OHLCV quality','Schema / chronology / coverage','BLOCKED'],['Engine admission','Validated data contract','DISABLED']]))}`}
function diagnostics(){return `<div class="grid four">${metric('Production gate','BLOCK','NO RELEASE AUTHORIZATION','red')}${metric('Staging preview','STATIC','GITHUB PAGES ONLY','gold')}${metric('Real authentication','NONE','NO CREDENTIALS COLLECTED')}${metric('Database','NONE','NO PERSISTENCE')}</div>${section('Operational readiness',table(['COMPONENT','STATUS','NOTE'],[['EDIE WEB runtime','NOT DEPLOYED','Public static preview only'],['GitHub Pages','PREVIEW','No backend'],['Gigantum / ARJUM','NOT_CONNECTED','No API calls'],['Production persistence','BLOCKED','Separate infrastructure required'],['Scanner execution','DISABLED','No verified data']]))}`}
const pages={control,market,stock,scanner,engine,broker,corporate,shareholder,portfolio,watchlist,reports,connectors,diagnostics};
function render(id){current=id;const m=modules.find(x=>x[0]===id)||modules[0];$('#title').textContent=m[2];$('#crumb').textContent=m[2];$('#subtitle').textContent=descriptions[id];$('#content').innerHTML=pages[id]();document.querySelectorAll('.nav-button').forEach(b=>{b.classList.toggle('active',b.dataset.id===id);b.setAttribute('aria-current',b.dataset.id===id?'page':'false')});$('#sidebar').classList.remove('open');$('#overlay').hidden=true;window.scrollTo(0,0)}
$('#nav').innerHTML=modules.map(([id,ico,name],i)=>`${[0,5,8,11].includes(i)?`<div class="sidebar-label">${i===0?'COMMAND CENTER':i===5?'INTELLIGENCE':i===8?'WORKSPACE':'OPERATIONS'}</div>`:''}<button class="nav-button" data-id="${id}"><span class="nav-icon">${ico}</span>${name}</button>`).join('');
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)render(b.dataset.id)});$('#enter').addEventListener('click',()=>{$('#login').hidden=true;$('#app').hidden=false;render('control')});$('#exit').addEventListener('click',()=>{$('#app').hidden=true;$('#login').hidden=false});$('#toggle').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#overlay').hidden=!$('#sidebar').classList.contains('open')});$('#overlay').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#overlay').hidden=true});$('#overview').addEventListener('click',()=>render('diagnostics'));
$('#content').addEventListener('click',e=>{if(e.target.closest('#lookup')){const val=$('#ticker').value.trim().toUpperCase().replace(/[^A-Z0-9.]/g,'').slice(0,12);showTickerChecklist(val)}if(e.target.closest('#run'))toast('Scanner unavailable: no validated OHLCV. No engine was executed.');if(e.target.closest('#watch-add'))toast('DEMO only. No watchlist entry was stored.');const t=e.target.closest('[data-tile]');if(t)toast(`${t.dataset.tile}: presentation only · engine not executed.`)});

// v2.1 controls: entirely in-memory, with no storage, API calls, or market computation.
const v21Messages={alerts:'Alert intelligence is disabled until validated market data and release approval exist.',source:'Source integrity requires official identity, timestamp, provenance, quality and authorization.',regime:'Market regime is unavailable. The displayed chart is synthetic and cannot support a market conclusion.',provenance:'Required: source kind, as-of timestamp, validation status and provenance evidence.',risk:'IDX long-only. No entry, stop loss, target, or probability is computed in this preview.',engines:'SCAN EBB, SCAN DSI and BANDAR DSI remain independent, locked, and unexecuted.'};
document.getElementById('content').addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(b)toast(v21Messages[b.dataset.action]||'DEMO only')});
document.getElementById('content').addEventListener('change',event=>{if(event.target.id==='v21-timeframe'){const x=document.getElementById('v21-feedback');if(x)x.textContent=event.target.value+' · DEMO · chart illustrative only';}if(event.target.id==='v21-broker'){const x=document.getElementById('v21-broker-label');if(x)x.textContent=event.target.value+' · no live records';}});

// v2.2: local-only quick navigation, no network, storage or authentication.
(()=>{
 const q=document.getElementById('quick-dialog'),input=document.getElementById('quick-input'),results=document.getElementById('quick-results');
 if(!q||!input||!results)return;
 const close=()=>{q.hidden=true;input.value='';};
 const update=()=>{const term=input.value.trim().toLocaleLowerCase();const matches=modules.filter(m=>(m[2]+' '+m[3]).toLocaleLowerCase().includes(term));results.replaceChildren();matches.forEach(m=>{const b=document.createElement('button');b.type='button';b.className='quick-result';b.textContent=m[2]+' · '+m[3];b.addEventListener('click',()=>{close();render(m[0]);});results.appendChild(b)});if(!matches.length){const d=document.createElement('p');d.textContent='Modul tidak ditemukan';results.appendChild(d);}};
 const open=()=>{if(document.getElementById('app').hidden)return;q.hidden=false;update();input.focus();};
 document.getElementById('quick-nav')?.addEventListener('click',open);document.getElementById('quick-close')?.addEventListener('click',close);input.addEventListener('input',update);q.addEventListener('click',e=>{if(e.target===q)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!q.hidden)close();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();q.hidden?open():close();}});
})();

// v2.3 isolated UI interactions: no fetch, storage, real data, or engine execution.
const engineInfo={
 'SCAN EBB':['Extreme Bandar Breakout','Breakout structure, volume participation, bandar confirmation','Validated OHLCV, timeframe and volume quality, historical events'],
 'SCAN DSI':['Demand & Smart-money Reversal','Qualified demand, reversal lifecycle, confluence and risk/reward','Validated demand history, broker evidence, walk-forward probability'],
 'BANDAR DSI':['Broker Flow Intelligence','Broker inventory, accumulation/distribution and consensus','Authorized broker data, provenance, reconciliation'],
 'SNIPER':['Demand × Retest × CHoCH','BOS, qualified demand, retest, lower-timeframe confirmation','Validated multi-timeframe OHLCV and participation'],
 'HOLYGRAIL':['Core / Seasonality','Independent momentum and seasonal research','Historical events and out-of-sample backtest'],
 'VMS-PRO':['Momentum & Volume','Standalone momentum and volume intelligence','Validated OHLCV and participation'],
 'FRI-01':['Five-Room Intelligence','Five independent research rooms','Room-specific validated source contracts'],
 'SIE':['Shareholder Intelligence','Ownership changes above 1%, 36-month target','KSEI, IDX and issuer source reconciliation'],
 'ONCI':['News & Catalyst Intelligence','Event provenance, ticker mapping and catalyst quality','Authorized official disclosures and news evidence'],
 'BIOGRAFI VOLUME':['Volume profile research','Price block volume distribution','Sufficient validated OHLCV window'],
 'P-FLOW':['Standalone demand momentum','Demand and price-flow research concept','Validated daily and weekly OHLCV'],
 'CORPORATE ACTION':['CA Intelligence','Issuer events and disclosure tracking','Verified IDX/OJK/issuer publications'],
 'Equity Research':['Institutional equity report','Report presentation concept','Verified data and documented research'],
 'Market Intelligence':['Market breadth review','Illustrative breadth dashboard','Verified IDX market breadth'],
 'Corporate Actions':['Event impact briefing','Corporate action presentation concept','Verified issuer event evidence']
};
const detailDialog=document.getElementById('detail-dialog');
const detailClose=document.getElementById('detail-close');
let detailReturnFocus=null;
function closeDetail(){detailDialog.hidden=true;detailReturnFocus?.focus();}
function showEngineDetail(name,origin){
 const [subtitle,purpose,requires]=engineInfo[name]||['Presentation module','Illustrative workspace','Authenticated source data'];
 detailReturnFocus=origin;
 document.getElementById('detail-title').textContent=name+' · DEMO';
 const body=document.getElementById('detail-body');body.replaceChildren();
 const add=(heading,value)=>{const box=document.createElement('div');box.className='detail-row';const h=document.createElement('strong');h.textContent=heading;const p=document.createElement('p');p.textContent=value;box.append(h,p);body.append(box)};
 add('Concept',subtitle);add('Scope',purpose);add('Evidence required',requires);add('Runtime status','NOT EXECUTED · no authenticated market source or backend');add('Governance','Read-only conceptual preview. Locked master engines remain unchanged.');
 detailDialog.hidden=false;detailClose.focus();
}
function showTickerChecklist(val){
 const box=document.getElementById('ticker-result');if(!box)return;
 const symbol=val||'—';box.replaceChildren();
 const title=document.createElement('strong');title.textContent='Ticker '+symbol+' · DEMO ONLY';box.append(title);
 const list=document.createElement('ul');
 ['OHLCV history: UNAVAILABLE','Source timestamp: UNAVAILABLE','Broker inventory: NOT_CONNECTED','Corporate actions: NOT VERIFIED','Entry / SL / TP / probability: NOT CALCULATED'].forEach(t=>{const li=document.createElement('li');li.textContent=t;list.append(li)});
 box.append(list);
}
document.getElementById('content').addEventListener('click',e=>{const b=e.target.closest('[data-tile]');if(b)showEngineDetail(b.dataset.tile,b)});
detailClose.addEventListener('click',closeDetail);
detailDialog.addEventListener('click',e=>{if(e.target===detailDialog)closeDetail()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!detailDialog.hidden)closeDetail();if(e.key==='Tab'&&!detailDialog.hidden){const nodes=[...detailDialog.querySelectorAll('button:not([disabled])')];if(nodes.length){e.preventDefault();nodes[0].focus()}}});



// v2.4: interactive synthetic visualization, entirely deterministic and local.
// Never interpret synthetic shapes as market observations or trading signals.
const scenarioNames={neutral:'Neutral illustration',expansion:'Expansion illustration',compression:'Compression illustration'};
function scenarioWorkspace(){return `<section class="section v24-workspace" aria-label="Synthetic market visualization"><div class="section-head"><h2>Advanced Market Visualization <span class="state gray">SYNTHETIC DEMO</span></h2><span>NO IDX DATA</span></div><div class="v24-controls"><label for="v24-scenario">Visual scenario</label><select id="v24-scenario"><option value="neutral">Neutral illustration</option><option value="expansion">Expansion illustration</option><option value="compression">Compression illustration</option></select><label for="v24-view">Display</label><select id="v24-view"><option value="structure">Structure</option><option value="participation">Participation</option></select><button class="mini-btn" id="v24-reset" type="button">Reset visual</button></div><div class="grid two"><div class="card"><div class="section-head"><h2 id="v24-visual-title">Structure · Neutral illustration</h2><span>GENERATED SHAPE</span></div><div id="v24-chart" aria-live="polite"></div></div><div class="card"><h3>Interpretation guardrails</h3><p class="v24-copy" id="v24-description">Visual-only synthetic series. It is not IHSG, a ticker, an indicator, or an observed market regime.</p><div class="v24-steps"><span>01 · Source: synthetic</span><span>02 · Validation: unavailable</span><span>03 · Engine execution: disabled</span><span>04 · Trading signal: none</span></div></div></div></section>`}
function engineComparison(){return `<section class="section"><div class="section-head"><h2>Multi-Engine Workspace · Capabilities</h2><span>DESIGN ONLY</span></div><div class="v24-controls"><label for="v24-engine">Focus engine</label><select id="v24-engine"><option value="EBB">SCAN EBB</option><option value="DSI">SCAN DSI</option><option value="BANDAR">BANDAR DSI</option></select></div><div class="card" id="v24-engine-panel" aria-live="polite"></div></section>`}
function v24Chart(scenario='neutral',view='structure'){
 const vals=Array.from({length:32},(_,i)=>{
  const base= scenario==='expansion'? 93-i*1.6:scenario==='compression'? 93+Math.sin(i*.8)*(17-i*.38):93+Math.sin(i*.48)*15+Math.cos(i*.23)*8;
  return Math.max(19,Math.min(150,base+(view==='participation'?Math.cos(i*.95)*14:0)));
 });
 const points=vals.map((y,i)=>`${16+i*15.5},${y.toFixed(1)}`).join(' ');
 const bars=vals.map((y,i)=>`<rect x="${12+i*15.5}" y="${y.toFixed(1)}" width="9" height="${(164-y).toFixed(1)}" fill="${i%4===0?'#ebcc91':'#967346'}" opacity=".85"/>`).join('');
 return `<svg class="chart" viewBox="0 0 520 180" preserveAspectRatio="none" role="img" aria-label="Synthetic ${view} illustration, no market data"><g stroke="#344254" stroke-dasharray="4 7">${[30,70,110,150].map(y=>`<path d="M0 ${y} H520"/>`).join('')}</g>${view==='structure'?`<polyline points="${points}" fill="none" stroke="#dfb978" stroke-width="3" stroke-linejoin="round"/>`:bars}</svg><div class="legend">SYNTHETIC · NO TICKER · NO PRICE · NO VOLUME · NO SIGNAL</div>`;
}
const engineCopy={EBB:['Breakout evidence','Volume / price / breakout validation','OHLCV, volume, source provenance','LOCKED · NOT EXECUTED'],DSI:['Demand and reversal','Qualified demand, lifecycle and risk/reward','OHLCV, demand evidence, broker confirmation','LOCKED · NOT EXECUTED'],BANDAR:['Broker flow intelligence','Broker inventory, consensus and participation','Authenticated broker flow and source reconciliation','LOCKED · NOT EXECUTED']};
function updateV24(){const sc=document.getElementById('v24-scenario');if(sc){const view=document.getElementById('v24-view').value;document.getElementById('v24-chart').innerHTML=v24Chart(sc.value,view);document.getElementById('v24-visual-title').textContent=`${view==='structure'?'Structure':'Participation'} · ${scenarioNames[sc.value]}`;document.getElementById('v24-description').textContent=`${scenarioNames[sc.value]} — a deterministic synthetic shape for UI inspection only. No source data, indicator, price, or trading conclusion is represented.`}const e=document.getElementById('v24-engine');if(e){const v=engineCopy[e.value];document.getElementById('v24-engine-panel').innerHTML=`<div class="v24-engine-grid"><div><span class="label">PURPOSE</span><strong>${v[0]}</strong></div><div><span class="label">ANALYTICAL FOCUS</span><strong>${v[1]}</strong></div><div><span class="label">REQUIRED EVIDENCE</span><strong>${v[2]}</strong></div><div><span class="label">RUNTIME STATUS</span><strong class="v24-block">${v[3]}</strong></div></div><p class="micro">Independent read-only engine concept. No calculation or cross-engine execution is performed.</p>`}}
const priorRender=render;
render=function(id){priorRender(id);updateV24()};
document.getElementById('content').addEventListener('change',e=>{if(['v24-scenario','v24-view','v24-engine'].includes(e.target.id))updateV24()});
document.getElementById('content').addEventListener('click',e=>{if(e.target.closest('#v24-reset')){document.getElementById('v24-scenario').value='neutral';document.getElementById('v24-view').value='structure';updateV24()}});


// v2.5 — institutional research terminal. All interactions are local and ephemeral.
